import { readFile } from "node:fs/promises";
import * as path from "node:path";
import type { ExtensionAPI, ExtensionCommandContext, ExtensionContext } from "@oh-my-pi/pi-coding-agent";
import {
	buildAgentHandoffFailure,
	buildAgentHandoffPrompt,
	buildAgentHandoffStatus,
	buildLaunchProps,
	buildTidewaveToolCall,
	DEFAULT_TIDEWAVE_MCP_URL,
	extractMcpToolText,
	extractSourceWindow,
	normalizeInspectTarget,
	parseCommandArgs,
	parseTidewaveMcpUrl,
} from "./helpers";
import frontendFixPrompt from "./prompts/frontend-fix.md" with { type: "text" };
import quickFixSchema from "./prompts/quick-fix-schema.json";

const WINDOW_ID = "phoenix-inspector";
const WINDOW_TITLE = "Phoenix Inspector";

interface QmlBridgeLike {
	launch(
		id: string,
		filePath: string,
		options?: { title?: string; width?: number; height?: number; props?: Record<string, unknown> },
	): Promise<unknown>;
	dispose(): Promise<void>;
	waitForEvent(id: string, timeoutMs?: number): Promise<Array<{ name?: string; payload: Record<string, unknown> }>>;
	sendMessage(id: string, payload: Record<string, unknown>): Promise<void>;
}

interface QmlRuntime {
	QmlBridge: new () => QmlBridgeLike;
	isDisplayAvailable(): boolean;
	isBridgeAvailable(): boolean;
}

let sharedBridge: QmlBridgeLike | null = null;
let sharedEventLoopAbort: AbortController | null = null;
let activeContext: ExtensionContext | ExtensionCommandContext | null = null;
let tidewaveRequestId = 0;

function inspectorQmlPath(): string {
	return path.resolve(import.meta.dir, "inspector.qml");
}

function getQmlRuntime(pi: ExtensionAPI): QmlRuntime {
	const runtime = pi.pi as Partial<QmlRuntime>;
	if (typeof runtime.QmlBridge !== "function") {
		throw new Error("Phoenix inspector runtime is missing QmlBridge export from @oh-my-pi/pi-coding-agent.");
	}
	if (typeof runtime.isDisplayAvailable !== "function") {
		throw new Error("Phoenix inspector runtime is missing isDisplayAvailable export from @oh-my-pi/pi-coding-agent.");
	}
	if (typeof runtime.isBridgeAvailable !== "function") {
		throw new Error("Phoenix inspector runtime is missing isBridgeAvailable export from @oh-my-pi/pi-coding-agent.");
	}
	return runtime as QmlRuntime;
}

function ensureDisplayOrThrow(ctx: ExtensionContext | ExtensionCommandContext, qml: QmlRuntime): void {
	if (qml.isDisplayAvailable()) return;
	const message = "Phoenix inspector requires a graphical display (DISPLAY or WAYLAND_DISPLAY).";
	ctx.ui.notify(message, "error");
	throw new Error(message);
}

function ensureBridgeBinaryOrThrow(ctx: ExtensionContext | ExtensionCommandContext, qml: QmlRuntime): void {
	if (qml.isBridgeAvailable()) return;
	const message = "Phoenix inspector bridge binary is unavailable. Build it with: cd packages/qml && bun run build:bridge";
	ctx.ui.notify(message, "error");
	throw new Error(message);
}

function getOrCreateBridge(qml: QmlRuntime): QmlBridgeLike {
	if (!sharedBridge) sharedBridge = new qml.QmlBridge();
	return sharedBridge;
}

async function disposeBridge(): Promise<void> {
	sharedEventLoopAbort?.abort();
	sharedEventLoopAbort = null;
	activeContext = null;
	if (!sharedBridge) return;
	await sharedBridge.dispose();
	sharedBridge = null;
}

function launchErrorMessage(error: unknown): string {
	const message = error instanceof Error ? error.message : String(error);
	if (/bridge.+(missing|unavailable)|build:bridge/i.test(message)) {
		return "Phoenix inspector bridge binary is unavailable. Build it with: cd packages/qml && bun run build:bridge";
	}
	return `Failed to launch Phoenix inspector: ${message}`;
}

function errorMessage(error: unknown): string {
	return error instanceof Error ? error.message : String(error);
}

function getActiveContextOrThrow(): ExtensionContext | ExtensionCommandContext {
	if (activeContext) return activeContext;
	throw new Error("Phoenix inspector is not attached to an active Spell session.");
}

function payloadString(payload: Record<string, unknown>, key: string): string | undefined {
	const value = payload[key];
	return typeof value === "string" && value.trim().length > 0 ? value.trim() : undefined;
}

function payloadRecord(payload: Record<string, unknown>, key: string): Record<string, unknown> | undefined {
	const value = payload[key];
	return value && typeof value === "object" && !Array.isArray(value) ? (value as Record<string, unknown>) : undefined;
}

function payloadNumber(payload: Record<string, unknown>, key: string): number | undefined {
	const value = payload[key];
	if (typeof value === "number" && Number.isFinite(value)) return value;
	if (typeof value === "string" && value.trim().length > 0) {
		const parsed = Number.parseInt(value.trim(), 10);
		if (!Number.isNaN(parsed)) return parsed;
	}
	return undefined;
}

async function resolveTidewaveMcpUrl(cwd: string): Promise<string> {
	const configPath = path.join(cwd, ".spell", "mcp.json");
	try {
		const raw = await readFile(configPath, "utf8");
		return parseTidewaveMcpUrl(raw) ?? DEFAULT_TIDEWAVE_MCP_URL;
	} catch (_error) {
		return DEFAULT_TIDEWAVE_MCP_URL;
	}
}

class TidewaveMcpClient {
	constructor(private readonly baseUrl: string) {}

	async callTool(name: string, args: Record<string, unknown>): Promise<string> {
		const response = await fetch(this.baseUrl, {
			method: "POST",
			headers: {
				Accept: "application/json, text/event-stream",
				"Content-Type": "application/json",
			},
			body: JSON.stringify(buildTidewaveToolCall(++tidewaveRequestId, name, args)),
		});

		if (!response.ok) {
			throw new Error(`Tidewave ${name} failed with ${response.status} ${response.statusText}`);
		}

		return extractMcpToolText(await response.json());
	}
}

async function readSourceExcerptFromTool(
	cwd: string,
	requestedPath: string,
	offset: number,
	limit: number,
): Promise<string> {
	const sourcePath = path.isAbsolute(requestedPath) ? requestedPath : path.join(cwd, requestedPath);
	const content = await readFile(sourcePath, "utf8");
	return extractSourceWindow(content, offset, limit);
}

async function replyToWindow(
	bridge: QmlBridgeLike,
	requestId: string | undefined,
	payload: Record<string, unknown>,
): Promise<void> {
	if (!requestId) return;
	await bridge.sendMessage(WINDOW_ID, { _rid: requestId, ...payload });
}

async function handleBridgePayload(
	payload: Record<string, unknown>,
	bridge: QmlBridgeLike,
	pi: ExtensionAPI,
): Promise<void> {
	const action = payloadString(payload, "action");
	if (action === "close") {
		sharedEventLoopAbort?.abort();
		sharedEventLoopAbort = null;
		return;
	}

	const requestId = payloadString(payload, "_rid");
	const tier = payloadString(payload, "_tier");
	const tool = payloadString(payload, "_tool");

	try {
		if (tier === "agent") {
			const assignment = payloadString(payload, "_assignment");
			if (!assignment) {
				throw new Error("Phoenix inspector agent handoff is missing the assignment text.");
			}

			const ctx = getActiveContextOrThrow();
			if (!ctx.model) {
				throw new Error("No active model is configured for the current Spell session.");
			}

			const context = payloadRecord(payload, "context");
			const wasIdle = ctx.isIdle();
			pi.sendUserMessage(buildAgentHandoffPrompt(WINDOW_ID, assignment, context), {
				deliverAs: "followUp",
			});

			const status = buildAgentHandoffStatus(wasIdle);
			await replyToWindow(bridge, requestId, {
				ok: true,
				status: status.status,
				message: status.message,
			});
			return;
		}

		if (tool === "read") {
			const requestedPath = payloadString(payload, "path");
			if (!requestedPath) {
				throw new Error("Source excerpt request is missing the path.");
			}

			const offset = payloadNumber(payload, "offset");
			const limit = payloadNumber(payload, "limit");
			if (offset === undefined || offset <= 0) {
				throw new Error("Source excerpt request is missing a valid offset.");
			}
			if (limit === undefined || limit <= 0) {
				throw new Error("Source excerpt request is missing a valid limit.");
			}

			const ctx = getActiveContextOrThrow();
			const result = await readSourceExcerptFromTool(ctx.cwd, requestedPath, offset, limit);
			await replyToWindow(bridge, requestId, { result });
			return;
		}

		if (!action) return;
	} catch (error) {
		const message = tier === "agent" ? buildAgentHandoffFailure(errorMessage(error)) : errorMessage(error);
		await replyToWindow(bridge, requestId, { error: message });
		activeContext?.ui.notify(message, "error");
	}
}

function startBridgeEventLoop(pi: ExtensionAPI, bridge: QmlBridgeLike): void {
	if (sharedEventLoopAbort) return;

	const abortController = new AbortController();
	sharedEventLoopAbort = abortController;

	void (async () => {
		try {
			while (!abortController.signal.aborted) {
				const events = await bridge.waitForEvent(WINDOW_ID);
				if (abortController.signal.aborted) break;
				for (const event of events) {
					await handleBridgePayload(event.payload, bridge, pi);
					if (abortController.signal.aborted) break;
				}
			}
		} catch (_error) {
			// The window closed or the bridge was disposed.
		} finally {
			if (sharedEventLoopAbort === abortController) {
				sharedEventLoopAbort = null;
			}
		}
	})();
}

async function launchInspector(
	pi: ExtensionAPI,
	targetInput: string | undefined,
	ctx: ExtensionContext | ExtensionCommandContext,
	qml: QmlRuntime,
): Promise<{ targetUrl: string }> {
	ensureDisplayOrThrow(ctx, qml);
	ensureBridgeBinaryOrThrow(ctx, qml);

	const hasExplicitTarget = typeof targetInput === "string" && targetInput.trim().length > 0;

	let targetUrl: URL;
	try {
		targetUrl = normalizeInspectTarget(targetInput);
	} catch (error) {
		const message = errorMessage(error);
		ctx.ui.notify(message, "error");
		throw new Error(message);
	}

	const tidewaveMcpUrl = await resolveTidewaveMcpUrl(ctx.cwd);
	const bridge = getOrCreateBridge(qml);
	activeContext = ctx;

