import QtQuick 2.15
import QtQuick.Controls 2.15
import QtQuick.Layouts 1.15
import QtQml 2.15
import Qt.labs.settings 1.0
import QtWebEngine

ApplicationWindow {
    id: root

    visible: true
    width: windowWidth || 1480
    height: windowHeight || 940
    title: windowTitle || "Phoenix LiveView Inspector"
    property var spellArmedTools: [
        "read"
    ]
    color: palette.background


    readonly property var palette: ({
        background: "#f5f5f2",
        surface: "#ffffff",
        surfaceMuted: "#faf9f7",
        border: "#e7e3dd",
        text: "#1f1f1f",
        textMuted: "#6b6761",
        accent: "#ff5a5f",
        accentSoft: "#fff1f1",
        success: "#17653c",
        warning: "#8d5f00",
        danger: "#b42318",
        shadow: "#140f0d"
    })
    WebEngineProfile {
        id: persistentProfile
        storageName: "spell-phoenix-inspector"
        offTheRecord: false
        persistentCookiesPolicy: WebEngineProfile.ForcePersistentCookies
    }

    readonly property string consolePrefix: "__PHX_INSPECTOR__:"
    readonly property string defaultOrigin: "http://127.0.0.1:4000"
    readonly property string injectedInspectorScript: `
(function() {
  const PREFIX = "__PHX_INSPECTOR__:";
  if (window.__spellPhxInspector && window.__spellPhxInspector.__installed) {
    return true;
  }

  const state = {
    enabled: true,
    currentTarget: null,
    overlay: null,
    observer: null
  };

  function ensureOverlay() {
    let overlay = document.getElementById("__spell-phx-inspector-overlay");
    if (!overlay) {
      overlay = document.createElement("div");
      overlay.id = "__spell-phx-inspector-overlay";
      Object.assign(overlay.style, {
        position: "fixed",
        zIndex: "2147483647",
        border: "2px solid rgba(255, 90, 95, 0.96)",
        background: "rgba(255, 90, 95, 0.12)",
        borderRadius: "12px",
        boxShadow: "0 18px 44px rgba(15, 23, 42, 0.18)",
        pointerEvents: "none",
        display: "none",
        transition: "all 60ms linear"
      });

      const label = document.createElement("div");
      label.id = "__spell-phx-inspector-overlay-label";
      Object.assign(label.style, {
        position: "absolute",
        left: "0px",
        top: "-30px",
        maxWidth: "420px",
        padding: "6px 10px",
        background: "rgba(17, 24, 39, 0.94)",
        color: "#ffffff",
        borderRadius: "999px",
        fontSize: "12px",
        fontFamily: "ui-monospace, SFMono-Regular, Menlo, monospace",
        whiteSpace: "nowrap",
        overflow: "hidden",
        textOverflow: "ellipsis"
      });

      overlay.appendChild(label);
      document.documentElement.appendChild(overlay);
    }

    state.overlay = overlay;
    return overlay;
  }

  function compactWhitespace(value) {
    return String(value || "").replace(/\\s+/g, " ").trim();
  }

  function elementLabel(el) {
    if (!(el instanceof Element)) return "";
    let label = el.tagName.toLowerCase();
    if (el.id) label += "#" + el.id;
    const classNames = compactWhitespace(el.className || "").split(" ").filter(Boolean).slice(0, 2);
    if (classNames.length > 0) {
      label += "." + classNames.join(".");
    }
    return label;
  }

  function placeOverlay(el) {
    const overlay = ensureOverlay();
    if (!(el instanceof Element)) {
      overlay.style.display = "none";
      return;
    }

    const rect = el.getBoundingClientRect();
    if ((rect.width <= 0 && rect.height <= 0) || rect.bottom < 0 || rect.right < 0) {
      overlay.style.display = "none";
      return;
    }

    overlay.style.display = "block";
    overlay.style.left = rect.left + "px";
    overlay.style.top = rect.top + "px";
    overlay.style.width = Math.max(0, rect.width) + "px";
    overlay.style.height = Math.max(0, rect.height) + "px";
    overlay.firstChild.textContent = elementLabel(el);
  }

  function textPreview(el) {
    if (!(el instanceof Element)) return "";
    const text = compactWhitespace(el.innerText || el.textContent || "");
    return text.slice(0, 240);
  }

  function attributeEntries(el) {
    if (!(el instanceof Element)) return [];
    return Array.from(el.attributes || []).slice(0, 60).map(attr => ({
      name: attr.name,
      value: String(attr.value).slice(0, 320)
    }));
  }

  function computedStyles(el) {
    if (!(el instanceof Element)) return {};
    const styles = getComputedStyle(el);
    return {
      display: styles.display,
      position: styles.position,
      color: styles.color,
      backgroundColor: styles.backgroundColor,
      fontSize: styles.fontSize,
      fontWeight: styles.fontWeight,
      lineHeight: styles.lineHeight,
      padding: styles.padding,
      margin: styles.margin,
      border: styles.border,
      borderRadius: styles.borderRadius,
      gap: styles.gap,
      flexDirection: styles.flexDirection,
      justifyContent: styles.justifyContent,
      alignItems: styles.alignItems,
      width: styles.width,
      height: styles.height
    };
  }

  function domPath(el) {
    if (!(el instanceof Element)) return "";
    const parts = [];
    let node = el;
    let depth = 0;

    while (node && depth < 8) {
      parts.unshift(elementLabel(node));
      node = node.parentElement;
      depth += 1;
    }

    return parts.join(" > ");
  }

  function ancestorTrail(el) {
    const out = [];
    let node = el;
    let depth = 0;

    while (node && depth < 6) {
      out.push(elementLabel(node));
      node = node.parentElement;
      depth += 1;
    }

    return out;
  }

  function parseAnnotation(raw) {
    const trimmed = compactWhitespace(raw);
    const symbolMatch = trimmed.match(/<\\/?([^>\\s]+)>/);
    const locationMatch = trimmed.match(/([A-Za-z0-9_./-]+\\.(?:heex|leex|ex|exs|html\\.heex)):(\\d+)/);
    const closing = /^<\\//.test(trimmed);
    return {
      raw: trimmed,
      kind: trimmed.indexOf("@caller") >= 0 ? "caller" : (symbolMatch ? "component" : "comment"),
      closing,
      symbol: symbolMatch ? symbolMatch[1] : "",
      file: locationMatch ? locationMatch[1] : "",
      line: locationMatch ? Number(locationMatch[2]) : 0
    };
  }

  function collectAnnotations(el) {
    const results = [];
    const seen = new Set();
    let node = el;
    let depth = 0;

    while (node && depth < 8) {
      let sibling = node.previousSibling;
      let scanned = 0;
      while (sibling && scanned < 12) {
        if (sibling.nodeType === Node.COMMENT_NODE) {
          const raw = compactWhitespace(sibling.textContent || "");
          if (raw && !seen.has(raw)) {
            const parsed = parseAnnotation(raw);
            parsed.depth = depth;
            seen.add(raw);
            results.push(parsed);
          }
        }
        sibling = sibling.previousSibling;
        scanned += 1;
      }

      node = node.parentElement;
      depth += 1;
    }

    return results;
  }

  function nearestPhxLoc(el) {
    let node = el;
    while (node) {
      if (node.getAttribute && node.getAttribute("data-phx-loc")) {
        return node.getAttribute("data-phx-loc");
      }
      node = node.parentElement;
    }
    return "";
  }

  function liveViewInfo(el) {
    const root = el.closest && (el.closest("[data-phx-main]") || el.closest("[data-phx-session]"));
    if (!root) return null;
    return {
      id: root.id || "",
      view: root.getAttribute("data-phx-view") || "",
      isMain: root.hasAttribute("data-phx-main")
    };
  }

  function emit(payload) {
    console.log(PREFIX + JSON.stringify(payload));
  }

  function inspectElement(el, trigger) {
    if (!(el instanceof Element)) return;
    const annotations = collectAnnotations(el);
    const primaryAnnotation = annotations.find(item => !!item.symbol && !item.closing) || annotations.find(item => !!item.file) || null;
    const rect = el.getBoundingClientRect();

    emit({
      type: "selection",
      trigger,
      pageUrl: location.href,
      pageTitle: document.title,
      tagName: el.tagName.toLowerCase(),
      id: el.id || "",
      classes: compactWhitespace(el.className || "").split(" ").filter(Boolean).slice(0, 16),
      role: el.getAttribute("role") || "",
      name: el.getAttribute("name") || "",
      text: textPreview(el),
      domPath: domPath(el),
      ancestorTrail: ancestorTrail(el),
      attributes: attributeEntries(el),
      dataset: Object.assign({}, el.dataset || {}),
      styles: computedStyles(el),
      phxLoc: nearestPhxLoc(el),
      phxComponent: el.getAttribute("data-phx-component") || "",
      liveView: liveViewInfo(el),
      annotations,
      primaryAnnotation,

