1#MT:export const DEFAULT_ORIGIN = "http://127.0.0.1:4000/";
2#WZ:export const DEFAULT_PATH = "/";
3#JX:export const DEFAULT_TIDEWAVE_MCP_URL = "http://localhost:4000/tidewave/mcp";
4#RW:
5#ZP:export function normalizeInspectTarget(input?: string): URL {
6#QN:	const trimmed = input?.trim();
7#RK:	if (!trimmed) return new URL(DEFAULT_PATH, DEFAULT_ORIGIN);
8#XW:
9#TZ:	try {
10#MV:		if (/^[a-zA-Z][a-zA-Z\d+.-]*:/.test(trimmed)) {
11#KY:			return new URL(trimmed);
12#PX:		}
13#WJ:		return new URL(trimmed, DEFAULT_ORIGIN);
14#KP:	} catch (_error) {
15#JQ:		throw new Error(`Invalid inspect target: ${trimmed}`);
16#WJ:	}
17#SH:}
18#KS:
