29#BJ:	targetUrl: URL,
30#VW:	hasExplicitTarget: boolean,
31#MH:	tidewaveMcpUrl: string,
32#QR:	quickFixSystemPrompt: string,
33#ZP:	quickFixOutputSchema: unknown,
