46#SS:	const trimmed = args.trim();
47#NX:	return trimmed.length > 0 ? trimmed : undefined;
48#YS:}
49#BN:
50#NH:export function parseTidewaveMcpUrl(rawConfig: string): string | undefined {
51#TZ:	try {
52#PY:		const parsed = JSON.parse(rawConfig) as {
53#MZ:			mcpServers?: Record<string, { url?: unknown }>;
54#MM:		};
55#XS:		const server = parsed.mcpServers?.tidewave;
56#VZ:		return typeof server?.url === "string" && server.url.trim().length > 0 ? server.url.trim() : undefined;
57#KP:	} catch (_error) {
58#NW:		return undefined;
59#KT:	}
60#MK:}
61#VW:
62#PJ:export interface TidewaveToolCallRequest {
