88#KV:export function extractMcpToolText(response: unknown): string {
89#MY:	if (!response || typeof response !== "object") {
90#RT:		throw new Error("Tidewave returned a non-object response.");
91#NQ:	}
92#JZ:
93#NH:	const maybeError = (response as { error?: { message?: unknown } }).error;
94#BW:	if (maybeError && typeof maybeError.message === "string" && maybeError.message.trim().length > 0) {
95#VW:		throw new Error(maybeError.message.trim());
96#JK:	}
97#ZT:
98#RQ:	const content = (response as { result?: { content?: Array<{ type?: unknown; text?: unknown }> } }).result?.content;
99#RH:	if (!Array.isArray(content)) {
100#YT:		throw new Error("Tidewave returned no content blocks.");
101#JP:	}
102#PJ:
103#RN:	const text = content
104#XV:		.filter(block => block && block.type === "text" && typeof block.text === "string")
105#KN:		.map(block => String(block.text).trim())
106#JY:		.filter(Boolean)
107#SQ:		.join("\n\n");
108#YQ:
109#VW:	if (text.length === 0) {
110#HN:		throw new Error("Tidewave returned no text content.");
111#TY:	}
112#QJ:
113#BX:	return text;
114#KW:}
