165#SN:export function extractSourceWindow(content: string, startLine: number, maxLines: number): string {
166#WX:	const lines = content.split(/\r?\n/);
167#JY:	const start = Math.max(1, startLine);
168#HP:	const end = Math.min(lines.length, start + Math.max(1, maxLines) - 1);
169#QM:	const width = String(end).length;
170#HM:
171#MQ:	return lines
172#WQ:		.slice(start - 1, end)
173#NW:		.map((text, index) => `${String(start + index).padStart(width, " ")} | ${text}`)
174#XS:		.join("\n");
175#TQ:}
