  function onMouseMove(event) {
    if (!state.enabled) return;
    const target = event.target instanceof Element ? event.target : null;
    state.currentTarget = target;
    placeOverlay(target);
  }

  function onClick(event) {
    if (!state.enabled) return;
    const target = event.target instanceof Element ? event.target : null;
    if (!target) return;
    event.preventDefault();
    event.stopPropagation();
    event.stopImmediatePropagation();
    state.currentTarget = target;
    placeOverlay(target);
    inspectElement(target, "click");
    state.enabled = false;
    emit({ type: "mode", inspectEnabled: false, pageUrl: location.href });
  }

  function onEscape(event) {
    if (event.key !== "Escape") return;
    state.enabled = false;
    ensureOverlay().style.display = "none";
    emit({ type: "mode", inspectEnabled: false, pageUrl: location.href });
  }

  function refreshOverlay() {
    if (state.enabled && state.currentTarget instanceof Element) {
      placeOverlay(state.currentTarget);
    }
  }

  function boot() {
    ensureOverlay();
    document.addEventListener("mousemove", onMouseMove, true);
    document.addEventListener("click", onClick, true);
    document.addEventListener("keydown", onEscape, true);
    window.addEventListener("scroll", refreshOverlay, true);
    window.addEventListener("resize", refreshOverlay, true);

    state.observer = new MutationObserver(function() {
      if (state.currentTarget && !document.contains(state.currentTarget)) {
        state.currentTarget = null;
        ensureOverlay().style.display = "none";
      } else {
        refreshOverlay();
      }
    });

    state.observer.observe(document.documentElement, {
      childList: true,
      subtree: true,
      attributes: true
    });

